from rich.console import Console
import io

class ProxyFile:
    def __init__(self, file):
        self._file = file
    def __getattr__(self, name):
        return getattr(self._file, name)
    def write(self, data):
        return self._file.write(data)
    def flush(self):
        return self._file.flush()

# Mock a file that is a TTY
class MockTTY:
    def isatty(self):
        return True
    def write(self, data):
        pass
    def flush(self):
        pass

tty_file = MockTTY()
proxy = ProxyFile(tty_file)
console = Console(file=proxy)
print(f"Is TTY: {console.is_terminal}")

# Mock a file that is NOT a TTY
class MockNonTTY:
    def isatty(self):
        return False
    def write(self, data):
        pass
    def flush(self):
        pass

non_tty_file = MockNonTTY()
proxy_non_tty = ProxyFile(non_tty_file)
console_non_tty = Console(file=proxy_non_tty)
print(f"Is TTY (non-tty): {console_non_tty.is_terminal}")
PY
